function tileAt(px,py){const x=Math.floor(px/TILE),y=Math.floor(py/TILE);return x>=0&&x<WORLD_W&&y>=0&&y<WORLD_H?world[y][x]:null;}
function isSolid(type){return !!type&&type!=='water'&&type!=='coral';}
function rectHits(x,y,w,h){const left=Math.floor(x/TILE),right=Math.floor((x+w-1)/TILE),top=Math.floor(y/TILE),bottom=Math.floor((y+h-1)/TILE);for(let ty=top;ty<=bottom;ty++)for(let tx=left;tx<=right;tx++)if(isSolid(world[ty]?.[tx]))return true;return false;}
function inWater(){for(let y=Math.floor(player.y/TILE);y<=Math.floor((player.y+player.h-1)/TILE);y++)for(let x=Math.floor(player.x/TILE);x<=Math.floor((player.x+player.w-1)/TILE);x++)if(world[y]?.[x]==='water')return true;return false;}
function moveAxis(axis,amount){const steps=Math.max(1,Math.ceil(Math.abs(amount)/4)),step=amount/steps;for(let i=0;i<steps;i++){const nx=player.x+(axis==='x'?step:0),ny=player.y+(axis==='y'?step:0);if(!rectHits(nx,ny,player.w,player.h)){player.x=nx;player.y=ny;}else{if(axis==='y'&&step>0)player.grounded=true;if(axis==='x')state.facing=step>0?1:-1;if(axis==='y')player.vy=0;return false;}}return true;}
function safePosition(x,y){return Number.isFinite(x)&&Number.isFinite(y)&&x>=0&&x+player.w<=WORLD_W*TILE&&y>=0&&y+player.h<=WORLD_H*TILE&&!rectHits(x,y,player.w,player.h);}
function findSafePosition(originX=player.x,originY=player.y){for(let radius=0;radius<12;radius++)for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){if(Math.max(Math.abs(dx),Math.abs(dy))!==radius)continue;const x=Math.max(0,Math.min(WORLD_W*TILE-player.w,Math.round(originX/TILE+dx)*TILE+(TILE-player.w)/2)),y=Math.max(0,Math.min(WORLD_H*TILE-player.h,Math.round(originY/TILE+dy)*TILE));if(safePosition(x,y)&&!rectHits(x,y+1,player.w,player.h))return{x,y};}return null;}
let lastSafe={x:player.x,y:player.y},stuckTimer=0;
if(!safePosition(player.x,player.y)){const spawn=findSafePosition(8*TILE,14*TILE-42);if(spawn){player.x=spawn.x;player.y=spawn.y;}else{player.x=8*TILE;player.y=14*TILE-42;}}
function unstuck(manual=true){let p=findSafePosition(player.x,player.y);if(!p)p=findSafePosition(lastSafe.x,lastSafe.y);if(!p)p={x:8*TILE,y:14*TILE-42};player.x=p.x;player.y=p.y;player.vx=player.vy=0;player.grounded=false;state.cast=null;if(manual)showToast('Safely recovered — your items and world are unchanged.');save();}
function respawn(){const p=findSafePosition(8*TILE,14*TILE-42)||{x:8*TILE,y:14*TILE-42};player.x=p.x;player.y=p.y;player.vx=player.vy=0;state.cast=null;showToast('Returned to Whispering Cove. Inventory preserved.');save();}
function movePlayer(dt){
  const left=keys.ArrowLeft||keys.KeyA||keys.touchLeft,right=keys.ArrowRight||keys.KeyD||keys.touchRight,swimming=inWater();
  const speed=swimming?112:180;player.vx=((right?1:0)-(left?1:0))*speed;if(player.vx)state.facing=Math.sign(player.vx);
  moveAxis('x',player.vx*dt);player.grounded=false;
  player.vy=Math.min(swimming?180:650,player.vy+(swimming?360:1200)*dt);
  if(swimming&&keys.touchJump)player.vy=-110;
  moveAxis('y',player.vy*dt);
  if(!player.grounded&&rectHits(player.x,player.y+2,player.w,player.h))player.grounded=true;
  player.x=Math.max(0,Math.min(WORLD_W*TILE-player.w,player.x));
  if(player.y>WORLD_H*TILE||!Number.isFinite(player.x+player.y)){unstuck(false);}
  if(safePosition(player.x,player.y)&&player.grounded){lastSafe={x:player.x,y:player.y};stuckTimer=0;}
  else if((left||right)&&Math.abs(player.vx)>0){stuckTimer+=dt;if(stuckTimer>5){unstuck(false);stuckTimer=0;}}
}

