   function nearbyDrop(){let best=null,bestDist=30;for(let i=0;i<state.dropped.length;i++){const d=state.dropped[i],dx=d.x-(player.x+player.w/2),dy=d.y-(player.y+player.h/2),dist=Math.sqrt(dx*dx+dy*dy);if(dist<bestDist){best={...d,index:i};bestDist=dist;}}return best;}
   function pickupDrop(){const d=nearbyDrop();if(!d)return false;if(d.id==='bait_worm')state.bait++;else if(blockDefs[d.id])state.counts[d.id]=(state.counts[d.id]||0)+1;else if(d.id)state.inventory.push({type:d.id,name:itemDefs[d.id]?.name||d.id,rarity:itemDefs[d.id]?.rarity||'Common'});state.dropped.splice(d.index,1);save();updateHud();showToast(`${itemDefs[d.id]?.name||d.id} picked up.`);return true;}
   function updatePickupPrompt(){const d=nearbyDrop(),p=$('pickupPrompt');if(!p)return;if(d){p.textContent=`E · Pick up ${itemDefs[d.id]?.name||d.id}`;p.classList.add('show');if(state.settings.autoPickup)pickupDrop();}else p.classList.remove('show');}
   function applySettings(){document.body?.classList.toggle('large-buttons',!!state.settings.largeButtons);document.body?.classList.toggle('high-contrast',!!state.settings.highContrast);document.body?.classList.toggle('reduced-effects',!!state.settings.reducedEffects);document.documentElement.style.setProperty('--touch-opacity',state.settings.buttonOpacity);}
-  function castLine(){if(state.cast){if(state.cast.phase==='bite'){startFight();return;}showToast('Your line is already in the water.');return;}const water=nearbyWater();if(!water){showToast('Get closer to a water edge to cast.');return;}if(player.x<water.x*TILE)state.facing=1;else state.facing=-1;const targetX=Math.max(0,Math.min(WORLD_W*TILE,(water.x+.5)*TILE));state.cast={phase:'waiting',x:targetX,y:water.y*TILE+4,timer:3.2+Math.random()*3.5,elapsed:0,fish:null,progress:0,tension:35,pull:0};showToast('Line cast — watching the water…');}
+  function castLine(){if(state.cast){if(state.cast.phase==='bite'){startFight();return;}showToast('Your line is already in the water.');return;}const water=nearbyWater();if(!water){showToast('Get closer to a water edge to cast.');return;}if(state.bait<=0){showToast('No worm bait remaining — craft or buy more.');return;}state.bait--;if(player.x<water.x*TILE)state.facing=1;else state.facing=-1;const targetX=Math.max(0,Math.min(WORLD_W*TILE,(water.x+.5)*TILE));state.cast={phase:'waiting',x:targetX,y:water.y*TILE+4,timer:3.2+Math.random()*3.5,elapsed:0,fish:null,progress:0,tension:35,pull:0};updateHud();save();showToast('Line cast with worm bait — watching the water…');}
   function chooseFish(){const roll=Math.random(),index=roll<.47?Math.floor(Math.random()*4):roll<.79?4+Math.floor(Math.random()*2):roll<.94?6+Math.floor(Math.random()*2):roll<.992?8:9;return initialFish[index];}
   function startFight(){if(!state.cast||state.cast.phase!=='bite')return;state.cast.phase='fight';state.cast.fish=chooseFish();state.cast.progress=0;state.cast.tension=40;state.cast.pull=Math.random()*6.28;$('fishKind').textContent=state.cast.fish.name.toUpperCase();$('fishAlert').classList.remove('show');$('fishingPanel').classList.add('active');showToast('Keep tension steady and reel in!');}
   function stopFishing(message){state.cast=null;$('fishAlert').classList.remove('show');$('fishingPanel').classList.remove('active');heldReel=false;if(message)showToast(message);}
   function catchFish(){const f=state.cast.fish,weight=f.weight[0]+Math.random()*(f.weight[1]-f.weight[0]),record=state.records[f.name]||{count:0,best:0};record.count++;record.best=Math.max(record.best,weight);state.records[f.name]=record;state.inventory.push({type:'fish',name:f.name,rarity:f.rarity,weight,value:Math.max(1,Math.round(f.value*(.7+weight/f.weight[1]*.8))),color:f.color});state.fishCaught++;state.coins+=Math.max(1,Math.round(f.value*.18));updateHud();save();showCatchModal(f,weight);stopFishing('Catch secured! Added to your bag.');}

